style.css:
@-moz-document domain("roblox.com") {
/* Wymuszenie przezroczystości domyślnych paneli i teł */
  body, 
  html, 
  #wrap, 
  .container-main, 
  .content, 
  .dark-theme, 
  .light-theme, 
  .gui-body,
  .rbx-body,
  .rbx-header,
  #container-main {
    background: transparent !important;
  }

  /* Nałożenie Twojego zdjęcia na główne tło całej witryny */
  html {
    background-image: url("https://imgur.com") !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
  }
}
